import json, random, subprocess, sys, time
def mk(saves):
    events=[]; nid=0; rng=random.Random(11)
    for _ in range(60000):
        events.append(['enqueue', nid, 0, 1, rng.randint(0,10**6)]); nid+=1
    for _ in range(saves):
        events.append(['save',1]); events.append(['enqueue', nid, 0, 1, rng.randint(0,10**6)]); nid+=1
    return {'runs':[{'banks':1,'load_balancers':1,'fifo_bytes':10**9,'pifo_bytes':10**9,
        'refill_batch':1,'sample_period':100000,'borders':[0,500000,2147483647],
        'policy':{'kind':'sff'},'events':events}]}
for saves in (0, 200, 2000, 20000):
    data=json.dumps(mk(saves)).encode()
    open('/tmp/b.json','wb').write(data)
    t0=time.monotonic()
    p=subprocess.run([sys.executable,'-I','-B','submission/cli.py'],stdin=open('/tmp/b.json','rb'),capture_output=True)
    print(f"saves={saves:6d} wall={time.monotonic()-t0:6.2f}s rc={p.returncode} out={len(p.stdout)//1000}KB")
PYEOF
